import functools
from collections import deque
from array import array


def _check_alphabet(alphabet: str):
    if not isinstance(alphabet, str):
        raise ValueError("alphabet must be a string")
    if len(alphabet) < 1:
        raise ValueError("empty alphabet")
    if len(alphabet) > 8:
        raise ValueError("alphabet has more than 8 characters")
    if len(set(alphabet)) != len(alphabet):
        raise ValueError("alphabet has duplicate characters")
    cmap = {c: i for i, c in enumerate(alphabet)}
    all_mask = (1 << len(alphabet)) - 1
    return cmap, all_mask


def _parse_class(s: str, pos: int, cmap, all_mask):
    n = len(s)
    pos += 1  # '['
    neg = False
    if pos < n and s[pos] == "^":
        neg = True
        pos += 1

    enum_mask = 0
    items = 0

    while pos < n:
        if s[pos] == "]":
            break

        if s[pos] == "\\":
            if pos + 1 >= n:
                raise ValueError("trailing backslash in character class")
            c1 = s[pos + 1]
            pos += 2
        else:
            c1 = s[pos]
            pos += 1

        items += 1

        if pos < n and s[pos] == "-" and pos + 1 < n and s[pos + 1] != "]":
            pos += 1
            if pos < n and s[pos] == "\\":
                if pos + 1 >= n:
                    raise ValueError("trailing backslash in character class")
                c2 = s[pos + 1]
                pos += 2
            else:
                c2 = s[pos]
                pos += 1

            if ord(c1) > ord(c2):
                raise ValueError("invalid character class range")

            x = ord(c1)
            y = ord(c2)
            for c, i in cmap.items():
                if x <= ord(c) <= y:
                    enum_mask |= 1 << i
        else:
            i = cmap.get(c1)
            if i is not None:
                enum_mask |= 1 << i

    if pos >= n:
        raise ValueError("unterminated character class")
    pos += 1  # ']'

    if items == 0:
        raise ValueError("empty character class")

    if neg:
        mask = all_mask & ~enum_mask
    else:
        mask = enum_mask

    return mask, pos


def _parse_element(s: str, pos: int, cmap, all_mask):
    if pos >= len(s):
        raise ValueError("unexpected end of pattern")

    ch = s[pos]

    if ch == "(":
        pos += 1
        body, pos = _parse_alt(s, pos, cmap, all_mask)
        if pos >= len(s) or s[pos] != ")":
            raise ValueError("unmatched group")
        pos += 1
        base = body

    elif ch == "[":
        mask, pos = _parse_class(s, pos, cmap, all_mask)
        base = ("set", mask)

    elif ch == ".":
        base = ("set", all_mask)
        pos += 1

    elif ch == "\\":
        if pos + 1 >= len(s):
            raise ValueError("trailing backslash")
        c = s[pos + 1]
        i = cmap.get(c)
        mask = 0 if i is None else (1 << i)
        base = ("set", mask)
        pos += 2

    else:
        i = cmap.get(ch)
        mask = 0 if i is None else (1 << i)
        base = ("set", mask)
        pos += 1

    if pos < len(s):
        q = s[pos]
        if q == "*":
            return ("star", base), pos + 1
        if q == "+":
            return ("plus", base), pos + 1
        if q == "?":
            return ("qm", base), pos + 1

    return base, pos


def _parse_concat(s: str, pos: int, cmap, all_mask):
    items = []
    n = len(s)

    while pos < n:
        ch = s[pos]
        if ch == "|" or ch == ")":
            break
        item, pos = _parse_element(s, pos, cmap, all_mask)
        items.append(item)

    if not items:
        return ("empty",), pos
    if len(items) == 1:
        return items[0], pos
    return ("concat", items), pos


def _parse_alt(s: str, pos: int, cmap, all_mask):
    alts = []
    while True:
        item, pos = _parse_concat(s, pos, cmap, all_mask)
        alts.append(item)
        if pos < len(s) and s[pos] == "|":
            pos += 1
            continue
        break

    if len(alts) == 1:
        return alts[0], pos
    return ("alt", alts), pos


def _parse_pattern(pattern: str, cmap, all_mask):
    if len(pattern) == 0:
        return ("empty",)
    ast, pos = _parse_alt(pattern, 0, cmap, all_mask)
    if pos != len(pattern):
        raise ValueError("unmatched parenthesis")
    return ast


def _build_nfa(ast, alphabet_len):
    trans = []
    eps = []
    A = alphabet_len

    def new_state():
        trans.append([0] * A)
        eps.append(0)
        return len(trans) - 1

    def compile(node):
        typ = node[0]

        if typ == "empty":
            s = new_state()
            t = new_state()
            eps[s] |= 1 << t
            return s, t

        if typ == "set":
            s = new_state()
            t = new_state()
            mask = node[1]
            m = mask
            while m:
                lsb = m & -m
                ci = lsb.bit_length() - 1
                trans[s][ci] |= 1 << t
                m ^= lsb
            return s, t

        if typ == "concat":
            items = node[1]
            if not items:
                s = new_state()
                t = new_state()
                eps[s] |= 1 << t
                return s, t

            s, e = compile(items[0])
            for nxt in items[1:]:
                ns, ne = compile(nxt)
                eps[e] |= 1 << ns
                s, e = s, ne
            return s, e

        if typ == "alt":
            items = node[1]
            if len(items) == 1:
                return compile(items[0])

            s = new_state()
            t = new_state()
            for body in items:
                bs, be = compile(body)
                eps[s] |= 1 << bs
                eps[be] |= 1 << t
            return s, t

        if typ == "star":
            bs, be = compile(node[1])
            s = new_state()
            t = new_state()
            eps[s] |= (1 << bs) | (1 << t)
            eps[be] |= (1 << bs) | (1 << t)
            return s, t

        if typ == "plus":
            bs, be = compile(node[1])
            s = new_state()
            t = new_state()
            eps[s] |= 1 << bs
            eps[be] |= (1 << bs) | (1 << t)
            return s, t

        if typ == "qm":
            bs, be = compile(node[1])
            s = new_state()
            t = new_state()
            eps[s] |= (1 << bs) | (1 << t)
            eps[be] |= 1 << t
            return s, t

        raise ValueError("invalid AST node")

    start, end = compile(ast)
    return trans, eps, start, 1 << end


def _build_dfa_from_nfa(trans, eps, start, accept_mask):
    k = len(trans)
    a = len(trans[0]) if trans else 0

    closure = [0] * k
    for i in range(k):
        seen = 0
        stack = 1 << i
        while stack:
            lsb = stack & -stack
            v = lsb.bit_length() - 1
            stack ^= lsb
            if seen & lsb:
                continue
            seen |= lsb
            stack |= eps[v] & ~seen
        closure[i] = seen

    def closure_of(mask):
        res = 0
        m = mask
        while m:
            lsb = m & -m
            i = lsb.bit_length() - 1
            res |= closure[i]
            m ^= lsb
        return res

    start_subset = closure_of(1 << start)
    state_map = {start_subset: 0}
    subsets = [start_subset]
    dfa_trans = [[0] * a for _ in range(1)]
    dfa_accept = [bool(start_subset & accept_mask)]
    q = [0]
    head = 0

    while head < len(q):
        idx = q[head]
        head += 1
        subset = subsets[idx]
        row = [0] * a

        for ci in range(a):
            union = 0
            m = subset
            while m:
                lsb = m & -m
                i = lsb.bit_length() - 1
                union |= trans[i][ci]
                m ^= lsb

            nxt = closure_of(union)
            nxt_idx = state_map.get(nxt, -1)
            if nxt_idx == -1:
                nxt_idx = len(subsets)
                state_map[nxt] = nxt_idx
                subsets.append(nxt)
                dfa_trans.append([0] * a)
                dfa_accept.append(bool(nxt & accept_mask))
                q.append(nxt_idx)
            row[ci] = nxt_idx

        dfa_trans[idx] = row

    return dfa_trans, dfa_accept


def _minimize_dfa(trans, accept, alphabet):
    n = len(trans)
    a = len(alphabet)

    if n == 1:
        return (tuple(trans[0]),), (accept[0],)

    blocks = []
    block_of = [0] * n

    acc_set = set(i for i, x in enumerate(accept) if x)
    non_set = set(i for i, x in enumerate(accept) if not x)

    for sset in (acc_set, non_set):
        if not sset:
            continue
        bid = len(blocks)
        blocks.append(sset)
        for p in sset:
            block_of[p] = bid

    non_bid = -1
    if non_set:
        for i, b in enumerate(blocks):
            if b == non_set:
                non_bid = i
                break

    work = deque()
    if non_bid != -1:
        for ci in range(a):
            work.append((non_bid, ci))

    while work:
        bid, ci = work.popleft()
        bset = blocks[bid]
        if not bset:
            continue

        targets = {}
        for p in bset:
            tb = block_of[trans[p][ci]]
            targets.setdefault(tb, []).append(p)

        for g in targets.values():
            g_set = set(g)
            counts = {}
            for p in g:
                pb = block_of[p]
                counts[pb] = counts.get(pb, 0) + 1

            for pb, cnt in counts.items():
                block = blocks[pb]
                if cnt == 0 or cnt == len(block):
                    continue

                if len(g) <= len(block):
                    inside = {p for p in g if block_of[p] == pb}
                    outside = block - inside
                    new_block = inside
                    blocks[pb] = outside
                else:
                    inside = []
                    outside = []
                    for p in block:
                        if p in g_set:
                            inside.append(p)
                        else:
                            outside.append(p)

                    if len(inside) <= len(outside):
                        new_block = set(inside)
                        blocks[pb] = set(outside)
                    else:
                        new_block = set(outside)
                        blocks[pb] = set(inside)

                new_bid = len(blocks)
                blocks.append(new_block)
                for p in new_block:
                    block_of[p] = new_bid

                work.append((pb, ci))
                work.append((new_bid, ci))

    start_block = block_of[0]
    mapping = {}
    for bid in range(len(blocks)):
        if bid == start_block:
            mapping[bid] = 0
        else:
            mapping[bid] = len(mapping)

    out_trans = [None] * len(blocks)
    out_accept = [False] * len(blocks)

    for bid, new_id in mapping.items():
        rep = blocks[bid][0]
        out_trans[new_id] = tuple(mapping[block_of[trans[rep][ci]]] for ci in range(a))
        out_accept[new_id] = accept[rep]

    return tuple(out_trans), tuple(out_accept)


@functools.lru_cache(maxsize=None)
def _build_min_dfa(pattern: str, alphabet: str):
    cmap, all_mask = _check_alphabet(alphabet)
    ast = _parse_pattern(pattern, cmap, all_mask)
    trans, eps, start, accept_mask = _build_nfa(ast, len(alphabet))
    dfa_trans, dfa_accept = _build_dfa_from_nfa(trans, eps, start, accept_mask)
    min_trans, min_accept = _minimize_dfa(dfa_trans, dfa_accept, alphabet)
    return min_trans, min_accept


def _decode_string(parent, code, ci, alphabet, shift, mask):
    parts = [alphabet[ci]]
    cur = code
    while cur != 0:
        info = parent[cur]
        p = info & mask
        c = info >> shift
        parts.append(alphabet[c])
        cur = p
    parts.reverse()
    return "".join(parts)


def _distinguish_min_dfa(dfa1, dfa2, alphabet: str):
    trans1, acc1_tuple = dfa1
    trans2, acc2_tuple = dfa2

    if acc1_tuple[0] != acc2_tuple[0]:
        return ""

    n1 = len(acc1_tuple)
    n2 = len(acc2_tuple)
    stride = n2
    total = n1 * n2
    a = len(alphabet)

    flat1 = [x for row in trans1 for x in row]
    flat2 = [x for row in trans2 for x in row]
    acc1 = bytearray(acc1_tuple)
    acc2 = bytearray(acc2_tuple)

    if total <= (1 << 29) - 1:
        shift = 29
        mask = (1 << shift) - 1
        sentinel = 0xFFFFFFFF
        parent = array("I", [sentinel]) * total
        code_type = "I"
    else:
        shift = 61
        mask = (1 << shift) - 1
        sentinel = 0xFFFFFFFFFFFFFFFF
        parent = array("Q", [sentinel]) * total
        code_type = "Q"

    current = array(code_type, [0])

    while current:
        nxt = array(code_type)
        append = nxt.append

        for code in current:
            s1, s2 = divmod(code, stride)
            r1 = s1 * a
            r2 = s2 * a

            for ci in range(a):
                ns1 = flat1[r1 + ci]
                ns2 = flat2[r2 + ci]

                if acc1[ns1] != acc2[ns2]:
                    return _decode_string(parent, code, ci, alphabet, shift, mask)

                ncode = ns1 * stride + ns2
                if parent[ncode] == sentinel:
                    parent[ncode] = code | (ci << shift)
                    append(ncode)

        current = nxt

    return None


def min_dfa_size(pattern: str, alphabet: str) -> int:
    _, accept = _build_min_dfa(pattern, alphabet)
    return len(accept)


def distinguish(p1: str, p2: str, alphabet: str) -> str | None:
    d1 = _build_min_dfa(p1, alphabet)
    d2 = _build_min_dfa(p2, alphabet)
    return _distinguish_min_dfa(d1, d2, alphabet)
